# shellcheck shell=bash disable=SC2154  # variables come from apply-theme.sh and the earlier parts
# scripts/theme.d/10-zathura.sh: part of apply-theme.sh, sourced in order in the same shell (not run on its own)
# ==========================================
# 10. Zathura PDF Viewer (colors.zathurarc -> ~/.cache/theme/zathurarc)
# ==========================================
cat <<EOF > "$CACHE_DIR/zathurarc"
# Generated by apply-theme.sh (Dotfiles Color Engine)
set font "$FONT_UI 10"
set default-bg "$BG"
set default-fg "$FG"
set statusbar-bg "$BG_ALT"
set statusbar-fg "$FG"
set inputbar-bg "$BG"
set inputbar-fg "$FG"
set notification-bg "$BG_ALT"
set notification-fg "$FG"
set notification-error-bg "$BG_ALT"
set notification-error-fg "$ANSI_RED"
set notification-warning-bg "$BG_ALT"
set notification-warning-fg "$ANSI_YELLOW"
set highlight-color "$BG_VISUAL"
set highlight-active-color "$ACCENT"
set completion-bg "$BG_ALT"
set completion-fg "$FG"
set completion-highlight-bg "$BG_VISUAL"
set completion-highlight-fg "$FG"
set index-bg "$BG"
set index-fg "$FG"
set index-active-bg "$BG_VISUAL"
set index-active-fg "$FG"
set recolor-lightcolor "$BG"
set recolor-darkcolor "$FG"
EOF

mkdir -p "$HOME/.config/zathura"
ln -sf "$CACHE_DIR/zathurarc" "$HOME/.config/zathura/colors.zathurarc"

